import torch
from torch.utils.cpp_extension import load_inline

# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void rms_norm_kernel(
    const half* __restrict__ input,
    half* __restrict__ output,
    const float eps,
    const int batch_size,
    const int num_features,
    const int spatial_elements
) {
    // Each block handles one batch element
    int batch_idx = blockIdx.x;
    if (batch_idx >= batch_size) return;

    // Shared memory for reduction
    extern __shared__ float sdata[];

    const int elements_per_batch = num_features * spatial_elements;
    const int input_offset = batch_idx * elements_per_batch;
    const int output_offset = batch_idx * elements_per_batch;

    // Compute sum of squares for this batch element
    float sum_sq = 0.0f;
    for (int i = threadIdx.x; i < elements_per_batch; i += blockDim.x) {
        half val = input[input_offset + i];
        float fval = __half2float(val);
        sum_sq += fval * fval;
    }

    sdata[threadIdx.x] = sum_sq;
    __syncthreads();

    // Reduction in shared memory
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            sdata[threadIdx.x] += sdata[threadIdx.x + s];
        }
        __syncthreads();
    }

    // Compute RMS
    float rms = sqrtf(sdata[0] / num_features + eps);
    float inv_rms = 1.0f / rms;

    // Normalize
    for (int i = threadIdx.x; i < elements_per_batch; i += blockDim.x) {
        half val = input[input_offset + i];
        float fval = __half2float(val);
        half normalized = __float2half(fval * inv_rms);
        output[output_offset + i] = normalized;
    }
}

void rms_norm_forward(
    const half* input,
    half* output,
    const float eps,
    const int batch_size,
    const int num_features,
    const int spatial_elements
) {
    const int threads_per_block = 256;
    const int blocks = batch_size;
    const size_t shared_mem_size = threads_per_block * sizeof(float);

    rms_norm_kernel<<<blocks, threads_per_block, shared_mem_size>>>(
        input, output, eps, batch_size, num_features, spatial_elements
    );
}
"""

# Python wrapper
def compile_and_run():
    # Load the CUDA extension
    module = load_inline(
        name="rms_norm_ext",
        cpp_sources=[],
        cuda_sources=[cuda_source],
        functions=["rms_norm_forward"],
        verbose=False
    )

    class ModelNew(torch.nn.Module):
        def __init__(self, num_features: int, eps: float = 1e-5):
            super(ModelNew, self).__init__()
            self.num_features = num_features
            self.eps = eps

        def forward(self, x: torch.Tensor) -> torch.Tensor:
            # Ensure input is contiguous and on GPU
            if not x.is_contiguous():
                x = x.contiguous()

            # Prepare output tensor
            output = torch.empty_like(x, dtype=torch.float16)

            # Get dimensions
            batch_size = x.shape[0]
            spatial_elements = 1
            for i in range(2, len(x.shape)):
                spatial_elements *= x.shape[i]

            # Launch kernel
            module.rms_norm_forward(
                x.data_ptr(),
                output.data_ptr(),
                self.eps,
                batch_size,
                self.num_features,
                spatial_elements
            )

            return output

    return ModelNew

# Create the model class
